import Fastify from "fastify";
const app = Fastify();
app.get("/books/:id", { schema: { params: { type: "object", required: ["id"], properties: { id: { type: "integer", minimum: 1 } } } } }, async request => ({ id: request.params.id }));
await app.listen({ port: 3000, host: "127.0.0.1" });
